WITH RecentTransactions AS (SELECT *, CONCAT(txn_type, ' ', merchant) AS txn_type_merchant FROM transactions WHERE account_id IN (8, 38)), transactions_stats AS (SELECT CASE WHEN amount >= 3600 THEN 'high' WHEN amount >= 900 THEN 'mid' ELSE 'low' END AS amount_bucket, MIN(txn_time) AS min_txn_time, MAX(amount) AS max_amount FROM RecentTransactions GROUP BY CASE WHEN amount >= 3600 THEN 'high' WHEN amount >= 900 THEN 'mid' ELSE 'low' END) SELECT amount_bucket, min_txn_time, max_amount FROM transactions_stats WHERE max_amount >= 3300 ORDER BY 1 LIMIT 10;
